// Hover and keyboard-focus definitions for links into the glossary.
// Any <a class="term" href="glossary.html#ID"> shows window.GLOSSARY_TIPS[ID].short (from
// assets/glossary-tips.js, generated by build.py). Clicking still opens the full entry.
(function () {
  var tips = window.GLOSSARY_TIPS || {};
  var terms = document.querySelectorAll('a.term[href*="glossary.html#"]');
  if (!terms.length) return;

  var tip = document.createElement("div");
  tip.className = "glossary-tip";
  tip.id = "glossary-tip";
  tip.setAttribute("role", "tooltip");
  tip.hidden = true;
  document.body.appendChild(tip);
  var current = null;

  function idOf(link) { return link.getAttribute("href").split("#")[1]; }

  function show(link) {
    var entry = tips[idOf(link)];
    if (!entry) return;
    current = link;
    tip.innerHTML = "";
    var head = document.createElement("strong");
    head.textContent = entry.term;
    var body = document.createElement("span");
    body.textContent = entry.short;
    var more = document.createElement("span");
    more.className = "glossary-tip-more";
    more.textContent = "Click for the full explanation";
    tip.append(head, body, more);
    tip.hidden = false;
    link.setAttribute("aria-describedby", tip.id);

    // Below the term, kept inside the viewport; above it if there is no room below.
    var r = link.getBoundingClientRect();
    var w = tip.offsetWidth, h = tip.offsetHeight, gap = 8;
    var left = Math.min(Math.max(8, r.left), document.documentElement.clientWidth - w - 8);
    var top = r.bottom + gap + h > window.innerHeight ? r.top - h - gap : r.bottom + gap;
    tip.style.left = left + window.scrollX + "px";
    tip.style.top = top + window.scrollY + "px";
  }

  function hide() {
    if (current) current.removeAttribute("aria-describedby");
    current = null;
    tip.hidden = true;
  }

  terms.forEach(function (link) {
    link.addEventListener("mouseenter", function () { show(link); });
    link.addEventListener("mouseleave", hide);
    link.addEventListener("focus", function () { show(link); });
    link.addEventListener("blur", hide);
  });
  document.addEventListener("keydown", function (e) { if (e.key === "Escape") hide(); });
  window.addEventListener("scroll", function () { if (current) hide(); }, { passive: true });
})();
